import os
from azure.identity import DefaultAzureCredential
from azure.keyvault.keys.crypto import CryptographyClient

def get_key_vault_url():
    key_vault_url = os.environ.get("AZURE_KEY_VAULT_URL")
    if not key_vault_url:
        raise ValueError("AZURE_KEY_VAULT_URL environment variable not set.")
    return key_vault_url

def get_cryptography_client(key_id: str) -> CryptographyClient:
    credential = DefaultAzureCredential()
    # The CryptographyClient expects the key_id to be the full URL to the key, e.g., https://<vault-name>.vault.azure.net/keys/<key-name>/<key-version>
    # So, we pass the key_id directly as the vault_url.
    return CryptographyClient(key_id, credential=credential)

from azure.keyvault.keys.crypto import SignatureAlgorithm
from security_client import get_cryptography_client
from security_models import SignRequest, SignResponse, VerifyRequest, VerifyResponse

def sign_payload(request: SignRequest) -> SignResponse:
    client = get_cryptography_client(request.key_id)

    # Map string algorithm to Enum if necessary. Assuming RSA-PSS or ECDSA for signing.
    # For this example, let's assume RS256 as a common signing algorithm.
    # The digest needs to be pre-hashed before sending to Key Vault.
    if request.algorithm.upper() == "RS256":
        akv_algorithm = SignatureAlgorithm.rs256
    elif request.algorithm.upper() == "RS384":
        akv_algorithm = SignatureAlgorithm.rs384
    elif request.algorithm.upper() == "RS512":
        akv_algorithm = SignatureAlgorithm.rs512
    else:
        raise ValueError(f"Unsupported signing algorithm: {request.algorithm}")

    sign_result = client.sign(akv_algorithm, request.digest)
    return SignResponse(
        signature=sign_result.signature,
        key_id=request.key_id,
        algorithm=request.algorithm
    )

def verify_payload(request: VerifyRequest) -> VerifyResponse:
    client = get_cryptography_client(request.key_id)

    if request.algorithm.upper() == "RS256":
        akv_algorithm = SignatureAlgorithm.rs256
    elif request.algorithm.upper() == "RS384":
        akv_algorithm = SignatureAlgorithm.rs384
    elif request.algorithm.upper() == "RS512":
        akv_algorithm = SignatureAlgorithm.rs512
    else:
        raise ValueError(f"Unsupported verification algorithm: {request.algorithm}")

    verify_result = client.verify(
        akv_algorithm,
        request.digest,
        request.signature
    )
    return VerifyResponse(
        is_valid=verify_result.is_valid,
        key_id=request.key_id,
        algorithm=request.algorithm
    )

import os
from azure.ai.contentmoderator import ContentModeratorClient
from azure.core.credentials import AzureKeyCredential

def check_payload_safety(text_payload: str, endpoint: str, key: str) -> dict:
    # Create a Content Moderator client
    client = ContentModeratorClient(endpoint=endpoint, credential=AzureKeyCredential(key))

    # Moderate the text payload
    text_moderation_result = client.text.moderate_text(text_payload)

    # Extract relevant information
    safety_report = {
        "original_text": text_payload,
        "profanity_detection": {
            "terms": []
        },
        "classification_detection": {
            "category1": None,
            "category2": None,
            "category3": None,
            "review_recommended": False
        }
    }

    if text_moderation_result.profanity_terms:
        for term in text_moderation_result.profanity_terms:
            safety_report["profanity_detection"]["terms"].append({
                "term": term.term,
                "index": term.index
            })

    if text_moderation_result.classification:
        classification = text_moderation_result.classification
        safety_report["classification_detection"]["category1"] = classification.category1.score if classification.category1 else None
        safety_report["classification_detection"]["category2"] = classification.category2.score if classification.category2 else None
        safety_report["classification_detection"]["category3"] = classification.category3.score if classification.category3 else None
        safety_report["classification_detection"]["review_recommended"] = classification.review_recommended

    return safety_report

